from collections import deque
def f(g):
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==bg and not seen[r][c]: seen[r][c]=True; dq.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==bg and not seen[r][c]: seen[r][c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and not seen[nr][nc]:
                seen[nr][nc]=True; dq.append((nr,nc))
    return [[4 if g[r][c]==bg and not seen[r][c] else g[r][c] for c in range(w)] for r in range(h)]
